// Release signing for local Gradle builds. android/ is generated by `expo prebuild`, so the
// signing setup is added here instead of being edited by hand.
//
// The upload key and its passwords come from Gradle properties OUTSIDE the repo, in
// %USERPROFILE%\.gradle\gradle.properties:
//   RECAP_UPLOAD_STORE_FILE, RECAP_UPLOAD_STORE_PASSWORD, RECAP_UPLOAD_KEY_ALIAS, RECAP_UPLOAD_KEY_PASSWORD
// Without them (CI, another computer) release builds still work, signed with the debug key, which
// Google Play rejects, so nothing unsigned can be uploaded by mistake.
const { withAppBuildGradle } = require('expo/config-plugins');

const HAS_KEY = "project.hasProperty('RECAP_UPLOAD_STORE_FILE')";

const RELEASE_SIGNING = `
        release {
            if (${HAS_KEY}) {
                storeFile file(RECAP_UPLOAD_STORE_FILE)
                storePassword RECAP_UPLOAD_STORE_PASSWORD
                keyAlias RECAP_UPLOAD_KEY_ALIAS
                keyPassword RECAP_UPLOAD_KEY_PASSWORD
            }
        }`;

function addReleaseSigning(gradle) {
  if (gradle.includes('RECAP_UPLOAD_STORE_FILE')) return gradle;

  // The release build type uses the debug key in Expo's template; point it at the upload key.
  const buildTypes = gradle.indexOf('buildTypes {');
  const releaseUsesDebug =
    /(release \{\s*\n(?:\s*\/\/.*\n)*\s*)signingConfig signingConfigs\.debug/;
  const tail = gradle.slice(buildTypes);
  if (buildTypes === -1 || !releaseUsesDebug.test(tail)) {
    throw new Error('withReleaseSigning: android/app/build.gradle has an unexpected layout');
  }
  gradle =
    gradle.slice(0, buildTypes) +
    tail.replace(
      releaseUsesDebug,
      `$1signingConfig ${HAS_KEY} ? signingConfigs.release : signingConfigs.debug`,
    );

  // A "release" signing config next to the debug one.
  if (!gradle.includes('signingConfigs {')) {
    throw new Error('withReleaseSigning: no signingConfigs block in android/app/build.gradle');
  }
  return gradle.replace('signingConfigs {', `signingConfigs {${RELEASE_SIGNING}`);
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};
module.exports.addReleaseSigning = addReleaseSigning;
